const { put } = require('@vercel/blob');
const { getDatabase } = require('../_db');
const allowedTypes = new Set(['image/jpeg', 'image/png', 'image/webp']);
module.exports = async function handler(req,res){if(req.method!=='POST')return res.status(405).json({error:'Método não permitido'});const conversationId=String(req.body?.conversationId||''),mimeType=String(req.body?.mimeType||'').toLowerCase(),fileName=String(req.body?.fileName||'foto').replace(/[^a-zA-Z0-9._-]/g,'-').slice(0,100),encoded=String(req.body?.data||'');if(!conversationId||!allowedTypes.has(mimeType)||!encoded)return res.status(400).json({error:'Envie uma imagem válida.'});const fileBuffer=Buffer.from(encoded,'base64');if(!fileBuffer.length||fileBuffer.length>4*1024*1024)return res.status(413).json({error:'A imagem deve ter no máximo 4 MB.'});try{const sql=getDatabase(),open=await sql`SELECT id FROM atendimentos WHERE id=${conversationId} AND status<>'SERVICO_FINALIZADO' LIMIT 1`;if(!open[0])return res.status(404).json({error:'Atendimento não encontrado ou encerrado.'});const blob=await put(`atendimentos/${conversationId}/${Date.now()}-${fileName}`,fileBuffer,{access:'private',contentType:mimeType,addRandomSuffix:true});const rows=await sql`INSERT INTO mensagens (atendimento_id,tipo_remetente,texto) VALUES (${conversationId},'CLIENTE','Imagem enviada') RETURNING id,tipo_remetente AS sender_type,texto AS body,criado_em AS created_at`,message=rows[0];await sql`INSERT INTO anexos_mensagem (mensagem_id,url_armazenamento,nome_arquivo,tipo_mime,tamanho_bytes) VALUES (${message.id},${blob.url},${fileName},${mimeType},${fileBuffer.length}) RETURNING id`;await sql`UPDATE atendimentos SET atualizado_em=NOW() WHERE id=${conversationId}`;return res.status(201).json({message:{...message,attachment_id:attachments[0].id,attachment_mime:mimeType},attachment:{fileName,mimeType,size:fileBuffer.length}})}catch(error){console.error('Photo upload failed',error);return res.status(500).json({error:'Não foi possível enviar a imagem.'})}};


